#!/bin/sh
# Run the Qt Quick component tests against the QML module generated by CMake.
#
# The generated qmldir prefers its embedded qrc copy, which is only present in
# the application binary. Strip that preference and point the module at the
# source QML files so qmltestrunner can load the same components the app uses.
set -eu

BUILD_DIR=${1:?usage: run_qml_tests.sh BUILD_DIR QMLTESTRUNNER}
RUNNER=${2:?usage: run_qml_tests.sh BUILD_DIR QMLTESTRUNNER}

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
REPO_DIR=$(CDPATH= cd -- "$SCRIPT_DIR/../.." && pwd)
TMP_DIR=$(mktemp -d "${TMPDIR:-/tmp}/oyama-qml-test.XXXXXX")
trap 'rm -rf "$TMP_DIR"' EXIT HUP INT TERM

mkdir -p "$TMP_DIR/OyamaHrt"
grep -v '^prefer ' "$BUILD_DIR/OyamaHrt/qmldir" > "$TMP_DIR/OyamaHrt/qmldir"
ln -s "$REPO_DIR/app" "$TMP_DIR/OyamaHrt/app"

QT_QUICK_CONTROLS_STYLE=Basic \
QT_QPA_PLATFORM=${QT_QPA_PLATFORM:-offscreen} \
QT_QUICK_BACKEND=${QT_QUICK_BACKEND:-software} \
    "$RUNNER" -input "$SCRIPT_DIR/qml" -import "$TMP_DIR"
